package primitives

import (
	"testing"
)

func TestNeuroChainKernelCoverage(t *testing.T) {
	InitNeuroChainKernel()
	vec := &CognitiveChainVector{HomeostasisEnergy: 1.0}
	count := 0
	for d := byte(0); d < 10; d++ {
		for p := byte(0); p < 10; p++ {
			for m := byte(0); m < 10; m++ {
				err := DispatchNeuroChain(d, p, m, vec)
				if err != nil {
					t.Fatalf("Failed to dispatch neuro chain [%d,%d,%d]: %v", d, p, m, err)
				}
				code := uint16(d)*100 + uint16(p)*10 + uint16(m)
				execCount := GetNeuroChainExecutionCount(code)
				if execCount != 1 {
					t.Errorf("Expected execution count 1 for code %d, got %d", code, execCount)
				}
				count++
			}
		}
	}
	if count != 1000 {
		t.Fatalf("Expected 1000 neuro chain primitives tested, got %d", count)
	}
	t.Logf("✅ Successfully verified 100%% execution coverage across all 1000 Neuro Chain Primitives. Final Entropy: %f", vec.LanguageEntropy)
}